import sys, math, itertools, random, bisect, heapq
from functools import lru_cache
from collections import Counter, defaultdict, deque
from pathlib import Path

def meeting_both(text):
    (m, n, x, y) = map(int, text.split())
    a = [[0] * (m + 1) for _ in range(n + 1)]
    b = [[0] * (m + 2) for _ in range(n + 2)]
    a[1][1] = b[n][m] = 1
    for j in range(1, n + 1):
        for i in range(1, m - n + j + 1):
            if (i, j) != (1, 1):
                a[j][i] = a[j - 1][i] + a[j][i - 1]
    for j in range(n, 0, -1):
        for i in range(m - n + j, 0, -1):
            if (i, j) != (m, n):
                b[j][i] = b[j + 1][i] + b[j][i + 1]
    return f'{a[y][x]}\n{b[y][x]}'

def meeting_one(text):
    return meeting_both(text).split()[0]
import sys
sys.stdout.write(meeting_one(sys.stdin.read()) + '\n')

import math, itertools, random, heapq, sys, subprocess, hashlib
