def expressions_model(text, leading_zero=True):
    (s, target) = text.split()
    target = int(target)
    n = len(s)
    answer = 0

    def visit(at, total, last):
        nonlocal answer
        if at == n:
            if total == target:
                answer += 1
            return
        value = 0
        for end in range(at, n):
            if not leading_zero and end > at and (s[at] == '0'):
                break
            value = value * 10 + int(s[end])
            if not at:
                visit(end + 1, value, value)
            else:
                visit(end + 1, total + value, value)
                visit(end + 1, total - value, -value)
                visit(end + 1, total - last + last * value, last * value)
    visit(0, 0, 0)
    return str(answer)

def expressions(text):
    return expressions_model(text, False)
import sys
sys.stdout.write(expressions(sys.stdin.read()) + '\n')
